const mysql = require('mysql2/promise');
const { SSMClient, GetParameterCommand } = require('@aws-sdk/client-ssm');

const ssm = new SSMClient({ region: process.env.AWS_REGION });

let pool = null;

async function getDbConfig() {
  const param = await ssm.send(new GetParameterCommand({
    Name: process.env.DB_CREDENTIALS_PATH,
    WithDecryption: true
  }));
  return JSON.parse(param.Parameter.Value);
}

async function getPool() {
  if (!pool) {
    const config = await getDbConfig();
    pool = mysql.createPool({
      host: config.host,
      user: config.username,
      password: config.password,
      database: config.database,
      port: config.port || 3306,
      connectionLimit: 5,
      waitForConnections: true,
      connectTimeout: 10000
    });
  }
  return pool;
}

// Sanitize helper - removes obvious attack patterns but is bypassable
function basicSanitize(input) {
  if (typeof input !== 'string') return '';
  // Remove comments and semicolons
  return input.replace(/--/g, '').replace(/;/g, '').replace(/\/\*/g, '');
}

exports.handler = async (event) => {
  try {
    const queryParams = event.queryStringParameters || {};
    const { category, sort_by, search } = queryParams;

    const db = await getPool();

    // Build product search query
    let query = 'SELECT id, name, price, description, category FROM products WHERE 1=1';
    const params = [];

    if (category) {
      // Using parameterized query for category
      query += ' AND category = ?';
      params.push(category);
    }

    if (search) {
      // Developer note: basicSanitize handles dangerous chars
      const sanitized = basicSanitize(search);
      // String concatenation used here for LIKE with wildcards
      query += ` AND (name LIKE '%${sanitized}%' OR description LIKE '%${sanitized}%')`;
    }

    // sort_by allows ordering results
    if (sort_by) {
      const allowedSorts = ['price', 'name', 'id'];
      if (allowedSorts.includes(sort_by)) {
        query += ` ORDER BY ${sort_by}`;
      } else {
        query += ' ORDER BY id';
      }
    }

    query += ' LIMIT 50';

    const [rows] = await db.execute(query, params);

    return {
      statusCode: 200,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        results: rows,
        count: rows.length
      })
    };
  } catch (error) {
    console.error('Query error:', error.message);
    return {
      statusCode: 500,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ error: 'Internal server error' })
    };
  }
};
